    "Grammar Connectors": [
        { korean: "-은/-는", romanization: "eun/neun", meaning: "Topic Marker - talk about the topic" },
        { korean: "-이/-가", romanization: "i/ga", meaning: "Subject Marker - specific subject/doer/w/adjective" },
        { korean: "-을/-를", romanization: "eul/reul", meaning: "Object Marker - receiver of the action" },
        { korean: "-에", romanization: "e", meaning: "Time & Location Marker - location & stative verbs (있다/existence), destination of an action, time expression, cause of a condition, counting of each pieces" },
        { korean: "-에서", romanization: "eseo", meaning: "Place Marker - where the action took place, origin/source" },
        { korean: "-부터...-까지", romanization: "buteo...kkaji", meaning: "From...to (time) - range of time, range of numbers" },
        { korean: "-에서...-까지", romanization: "eseo...kkaji", meaning: "From...to (location) - up until locations" },
        { korean: "-으로/-로", romanization: "euro/ro", meaning: "Direction - means of movement (택시 타고 가다), tool (using a tool/method), communication, ingredient, mark the status of a person doing something (as)" },
        { korean: "-과/-와", romanization: "gwa/wa", meaning: "And (nouns only) - 'and' between two nouns, 'with' when used with verbs" },
        { korean: "-하고", romanization: "hago", meaning: "And - also/too (nouns), can attach 도/은 after" },
        { korean: "-랑/-이랑", romanization: "rang/irang", meaning: "And/With - casual form of 과/와 (used in spoken Korean)" },
        { korean: "-고", romanization: "go", meaning: "And - (Verbs), same tense only" },
        { korean: "그리고", romanization: "geurigo", meaning: "And (Verbs), same or different tense" },
        { korean: "-도", romanization: "do", meaning: "Also/Too" },
        { korean: "-들", romanization: "deul", meaning: "Plural noun marker" },
        { korean: "-의", romanization: "ui", meaning: "Possessive Marker - 's" },
        { korean: "-(이)나", romanization: "(i)na", meaning: "Or - connects nouns as alternatives (e.g., 커피나 차 = coffee or tea)" },
        { korean: "-거나", romanization: "geona", meaning: "Or - connects verbs/adjectives as alternatives (e.g., 먹거나 자거나 = eat or sleep)" },
        { korean: "아니면", romanization: "animyeon", meaning: "Or/If not/Otherwise - used to suggest alternatives or conditions (e.g., 이거 아니면 저거 = this or/if not/otherwise that)" },
        { korean: "-같이/-처럼", romanization: "gachi/cheoreom", meaning: "Like/As - similarity/comparison (e.g., 친구같이/친구처럼 = like a friend)" },
        { korean: "-보다", romanization: "boda", 
        meaning: "Comparative Marker - more than / compared to (can add 더/덜 for more/less). Flexible (e.g., 사과가 바나나보다 비싸요 / 바나나보다 사과가 비싸요 = apples are more expensive than bananas)" },
        { korean: "한테", romanization: "hante", meaning: "To someone/for someone - casual" },
        { korean: "-에게", romanization: "ege", meaning: "To someone/for someone - formal" },
        { korean: "-께", romanization: "kke", meaning: "To someone/for someone - honorific (for respected people)" },
        { korean: "-한테서", romanization: "hanteseo", meaning: "From someone - casual" },
        { korean: "-에게서", romanization: "egeseo", meaning: "From someone - formal" },
        { korean: "-께서", romanization: "kkeseo", meaning: "From someone - honorific / Subject marker for respected people" },
        { korean: "-쯤", romanization: "jjeum", meaning: "About/Around - used with time, quantities, or amounts" },
        { korean: "-만", romanization: "man", meaning: "Only" },
        { korean: "-이/-가 아니다", romanization: "i/ga anida", meaning: "To not be - negates nouns (e.g., 학생이 아니에요 = is not a student)" },
        { korean: "안 / -지 않다", romanization: "an / ji anta", meaning: "Not - negates verbs/adjectives (e.g., 안 먹어요 / 먹지 않아요 = don't eat)" },
        { korean: "못 / -지 못하다", romanization: "mot / ji mothada", meaning: "Cannot - inability to do something (e.g., 못 먹어요 / 먹지 못해요 = can't eat)" },
        { korean: "-밖에", romanization: "bakke", meaning: "Only/Nothing but the noun (with negative verbs) - emphasizes limitation, must use negative verb form (e.g., 물밖에 없어요 = there's only water)" },
        { korean: "-마다", romanization: "mada", meaning: "Every (noun + 마다) - every noun" },
        { korean: "-께서", romanization: "kkeseo", meaning: "Subject marker (honorific) - replaces 이/가 for respected people (e.g., 선생님께서 오셨어요 = the teacher came)" },
        { korean: "-께서는", romanization: "kkeseoneun", meaning: "Topic marker (honorific) - replaces 은/는 for respected people (e.g., 할아버지께서는 = as for grandfather)" },
        { korean: "-(으)시-", romanization: "(eu)si", 
        meaning: "Honorific marker - adds respect to verbs (present: 가세요/가십니다 = go, past: 가셨어요/가셨습니다 = went, future: 가실 거예요/가시겠어요 = will go)" },
        { korean: "-(이)라서", romanization: "(i)raseo", meaning: "Because - used after nouns (e.g., 학생이라서 = because I'm a student)" },
        { korean: "-아서/-어서", romanization: "aseo/eoseo", meaning: "Because/So - reason connector for verbs/adjectives (e.g., 바빠서 = because I'm busy)" },
        { korean: "-때마다", romanization: "ttaemada", meaning: "Every time (when) - whenever an action happens (e.g., 집에 갈 때마다 = every time I go home)" },
        { korean: "-대로", romanization: "daero", meaning: "As, according to, the way/manner (e.g., 말대로 = as you said / according to what was said)" },
        { korean: "-마저", romanization: "majeo", meaning: "Even - emphasizes that this is the final/last item (e.g., 음식마저 먹었다 = even the food was eaten)" },
    ],

